pub fn decomposition(codepoint: u21, compatibility: bool) ?[]const u21 {
    var low: usize = 0; var high = decompositions.len;
    while (low < high) { const middle = low + (high - low) / 2; const entry = decompositions[middle];
        if (codepoint < entry.codepoint) high = middle else if (codepoint > entry.codepoint) low = middle + 1 else {
            if (entry.compatibility and !compatibility) return null; return decomposition_data[entry.offset .. entry.offset + entry.length];
        }
    } return null;
}

pub fn combiningClass(codepoint: u21) u8 {
    var low: usize = 0; var high = combining_classes.len;
    while (low < high) { const middle = low + (high - low) / 2; const entry = combining_classes[middle];
        if (codepoint < entry.codepoint) high = middle else if (codepoint > entry.codepoint) low = middle + 1 else return entry.class;
    } return 0;
}

pub fn compose(first: u21, second: u21) ?u21 {
    var low: usize = 0; var high = compositions.len;
    while (low < high) { const middle = low + (high - low) / 2; const entry = compositions[middle];
        if (first < entry.first or (first == entry.first and second < entry.second)) high = middle else if (first > entry.first or (first == entry.first and second > entry.second)) low = middle + 1 else return entry.composed;
    } return null;
}
